  "milestones": [
    {
      "task": "find spruce_trapdoor",
      "milestone_id": "find_spruce_trapdoor",
      "description": "Uses position_near_with_facing because this is a 'find' task — the player must navigate near the spruce trapdoor entrance and face it. Target is the center trapdoor at (0, 3, 4). max_distance=8 allows detection from a few blocks away since the trapdoors are at the building entrance and visible from the approach path. facing_tolerance=60 ensures the player is actually looking at the entrance.",
      "rules": [
        {
          "type": "position_near_with_facing",
          "params": {
            "target": [0, 3, 4],
            "max_distance": 8,
            "facing_tolerance": 60,
            "coordinate_frame": "spawn_relative"
          }
        }
      ]
    },
